//! Minimal CW1155-like multi-token contract for selector-resolved Vegeta S3 traffic.
use cosmwasm_std::{entry_point,to_json_binary,Addr,Binary,Deps,DepsMut,Env,MessageInfo,Response,StdError,StdResult,Uint128};use cw_storage_plus::{Map};use schemars::JsonSchema;use serde::{Deserialize,Serialize};use thiserror::Error;
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct InstantiateMsg{}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]#[serde(rename_all="snake_case")]pub enum ExecuteMsg{Mint{to:String,token_id:u64,amount:Uint128},SendFrom{from:String,to:String,token_id:u64,amount:Uint128},ApproveAll{operator:String,approved:bool}}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]#[serde(rename_all="snake_case")]pub enum QueryMsg{Balance{address:String,token_id:u64},ApprovedForAll{owner:String,operator:String}}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct AmountResponse{pub amount:Uint128}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct BoolResponse{pub value:bool}
const BALANCES:Map<(u64,&str),Uint128>=Map::new("balances");const APPROVALS:Map<(&str,&str),bool>=Map::new("approvals");
#[derive(Error,Debug,PartialEq)]pub enum ContractError{#[error("{0}")]Std(#[from]StdError),#[error("unauthorized")]Unauthorized,#[error("insufficient funds")]InsufficientFunds}
#[entry_point]pub fn instantiate(_deps:DepsMut,_:Env,_:MessageInfo,_:InstantiateMsg)->Result<Response,ContractError>{Ok(Response::new())}
#[entry_point]pub fn execute(deps:DepsMut,_:Env,info:MessageInfo,msg:ExecuteMsg)->Result<Response,ContractError>{match msg{ExecuteMsg::Mint{to,token_id,amount}=>{let to=deps.api.addr_validate(&to)?;credit(deps.storage,token_id,to.as_str(),amount)?;Ok(Response::new())},ExecuteMsg::SendFrom{from,to,token_id,amount}=>send_from(deps,info.sender,from,to,token_id,amount),ExecuteMsg::ApproveAll{operator,approved}=>{let op=deps.api.addr_validate(&operator)?;APPROVALS.save(deps.storage,(info.sender.as_str(),op.as_str()),&approved)?;Ok(Response::new())}}}
fn send_from(deps:DepsMut,sender:Addr,from:String,to:String,id:u64,amount:Uint128)->Result<Response,ContractError>{let from=deps.api.addr_validate(&from)?;let to=deps.api.addr_validate(&to)?;if sender!=from&&!APPROVALS.may_load(deps.storage,(from.as_str(),sender.as_str()))?.unwrap_or(false){return Err(ContractError::Unauthorized)};let x=BALANCES.may_load(deps.storage,(id,from.as_str()))?.unwrap_or_default();if x<amount{return Err(ContractError::InsufficientFunds)};BALANCES.save(deps.storage,(id,from.as_str()),&x.checked_sub(amount).map_err(StdError::overflow)?)?;credit(deps.storage,id,to.as_str(),amount)?;Ok(Response::new())}
fn credit(s:&mut dyn cosmwasm_std::Storage,id:u64,a:&str,n:Uint128)->StdResult<()>{let x=BALANCES.may_load(s,(id,a))?.unwrap_or_default();BALANCES.save(s,(id,a),&x.checked_add(n).map_err(StdError::overflow)?) }
#[entry_point]pub fn query(deps:Deps,_:Env,msg:QueryMsg)->StdResult<Binary>{match msg{QueryMsg::Balance{address,token_id}=>to_json_binary(&AmountResponse{amount:BALANCES.may_load(deps.storage,(token_id,address.as_str()))?.unwrap_or_default()}),QueryMsg::ApprovedForAll{owner,operator}=>to_json_binary(&BoolResponse{value:APPROVALS.may_load(deps.storage,(owner.as_str(),operator.as_str()))?.unwrap_or(false)})}}
#[cfg(test)]mod tests{use super::*;use cosmwasm_std::testing::{mock_dependencies,mock_env,mock_info};#[test]fn operator_can_move_only_approved_owner_balance(){let mut d=mock_dependencies();instantiate(d.as_mut(),mock_env(),mock_info("x",&[]),InstantiateMsg{}).unwrap();execute(d.as_mut(),mock_env(),mock_info("mint",&[]),ExecuteMsg::Mint{to:"alice".into(),token_id:7,amount:Uint128::new(5)}).unwrap();execute(d.as_mut(),mock_env(),mock_info("alice",&[]),ExecuteMsg::ApproveAll{operator:"operator".into(),approved:true}).unwrap();execute(d.as_mut(),mock_env(),mock_info("operator",&[]),ExecuteMsg::SendFrom{from:"alice".into(),to:"bob".into(),token_id:7,amount:Uint128::new(2)}).unwrap();assert_eq!(BALANCES.load(d.as_ref().storage,(7,"bob")).unwrap(),Uint128::new(2));}}
